class LRUCache {
    struct Node {
        int key, val;
        Node *prev, *next;
        Node(int k, int v) : key(k), val(v), prev(nullptr), next(nullptr) {}
    };

    int cap;
    unordered_map<int, Node*> map;      // key -> Node
    Node *head, *tail;                  // 两个哨兵，省掉判空

    void remove(Node* node) {
        node->prev->next = node->next;
        node->next->prev = node->prev;
    }

    void addFront(Node* node) {
        node->prev = head;
        node->next = head->next;
        head->next->prev = node;
        head->next = node;
    }

public:
    LRUCache(int capacity) {
        cap = capacity;
        head = new Node(0, 0);
        tail = new Node(0, 0);
        head->next = tail;
        tail->prev = head;
    }

    int get(int key) {
        auto it = map.find(key);
        if (it == map.end()) {
            return -1;
        }
        Node* node = it->second;
        remove(node);                   // 挪到头部，表示刚用过
        addFront(node);
        return node->val;
    }

    void put(int key, int value) {
        auto it = map.find(key);
        if (it != map.end()) {
            remove(it->second);
            delete it->second;
        }
        Node* node = new Node(key, value);
        map[key] = node;
        addFront(node);
        if ((int)map.size() > cap) {
            Node* last = tail->prev;    // 尾部是最久没用的
            remove(last);
            map.erase(last->key);
            delete last;
        }
    }
};

