type node struct {
	key, val   int
	prev, next *node
}

type LRUCache struct {
	cap        int
	m          map[int]*node // key -> 节点
	head, tail *node         // 两个哨兵，省掉判空
}

func Constructor(capacity int) LRUCache {
	head, tail := &node{}, &node{}
	head.next, tail.prev = tail, head
	return LRUCache{cap: capacity, m: map[int]*node{}, head: head, tail: tail}
}

func (c *LRUCache) remove(n *node) {
	n.prev.next, n.next.prev = n.next, n.prev
}

func (c *LRUCache) addFront(n *node) {
	n.prev, n.next = c.head, c.head.next
	c.head.next.prev = n
	c.head.next = n
}

func (c *LRUCache) Get(key int) int {
	n, ok := c.m[key]
	if !ok {
		return -1
	}
	c.remove(n)   // 挪到头部，表示刚用过
	c.addFront(n)
	return n.val
}

func (c *LRUCache) Put(key int, value int) {
	if old, ok := c.m[key]; ok {
		c.remove(old)
	}
	n := &node{key: key, val: value}
	c.m[key] = n
	c.addFront(n)
	if len(c.m) > c.cap {
		last := c.tail.prev  // 尾部是最久没用的
		c.remove(last)
		delete(c.m, last.key)
	}
}

